## Why This Is Asked
This question tests understanding of prefix-based searching using a practical, lightweight data structure. It combines Trie fundamentals with per-node augmentation to enable fast prefix queries in real time—useful in autocomplete systems, IP routing, and spell checking.

## Key Concepts
- **Trie structure**: Each node contains 26 children (one per letter) and maintains a pass counter representing how many words pass through that node
- **insert operation**: O(m) time, where m is word length; creates nodes as needed and increments pass at each node visited
- **count_with_prefix operation**: O(k) time, where k is prefix length; traverses to the prefix node and returns its pass counter
- **Handling duplicates**: Pass counters naturally accumulate, so duplicate insertions simply increment the counter without special handling

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Array(26).fill(null);
    this.pass = 0;
    this.isWord = false;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
  }

  insert(word) {
    let node = this.root;
    for (const char of word) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.next[idx]) node.next[idx] = new TrieNode();
      node.pass++;
      node = node.next[idx];
    }
    node.pass++;
    node.isWord = true;
  }

  countWithPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.next[idx]) return 0;
      node = node.next[idx];
    }
    return node.pass;
  }
}

// Example usage
const trie = new Trie();
['cat', 'car', 'cart', 'dog', 'dot'].forEach(w => trie.insert(w));
console.log(trie.countWithPrefix('ca')); // 3
console.log(trie.countWithPrefix('car')); // 1
console.log(trie.countWithPrefix('d')); // 2
console.log(trie.countWithPrefix('do')); // 2
```

## Why This Is Asked
Tests ability to frame a sign-assignment problem as a DP and implement both memoization and tabulation, a common interview pattern.

## Key Concepts
- DP state reduction to subset sum
- Space optimization with a 1D array
- Memoization vs bottom-up trade-offs

## Code Example
```javascript
// Tabulation and Memo versions
function countTargetSumTab(nums, S) {
  const total = nums.reduce((a,b)=>a+b,0);
  if (Math.abs(S) > total || (total+S)%2 !== 0) return 0;
  const target = (total+S)/2;
  const dp = Array(target+1).fill(0);
  dp[0] = 1;
  for (const n of nums) {
    for (let t = target; t >= n; t--) dp[t] += dp[t-n];
  }
  return dp[target];
}

function countTargetSumMemo(nums, S) {
  const total = nums.reduce((a,b)=>a+b,0);
  if (Math.abs(S) > total || (total+S)%2 !== 0) return 0;
  const target = (total+S)/2;
  const memo = new Map();
  function dfs(i, sum){
    if (sum > target) return 0;
    if (i === nums.length) return sum === target ? 1 : 0;
    const key = i+':'+sum;
    if (memo.has(key)) return memo.get(key);
    const res = dfs(i+1, sum+nums[i]) + dfs(i+1, sum);
    memo.set(key, res);
    return res;
  }
  return dfs(0,0);
}
```

## Why This Is Asked

This question probes understanding of sorting trade-offs (in-place memory vs stability vs constants) and how hybrid approaches balance speed, especially relevant in finance and large-scale data.

## Key Concepts

- 3-way partitioning in quicksort
- Insertion sort for small slices
- In-place sorting and O(1) extra space
- Average vs worst-case complexities; pivot choice

## Code Example

```javascript
function sortHybrid(a){
  const TH = 16;
  const swap=(i,j)=>{ [a[i],a[j]]=[a[j],a[i]]; };
  const insertSort=(l,r)=>{
    for(let i=l+1;i<=r;i++){
      let x=a[i], j=i-1;
      while(j>=l && a[j]>x){ a[j+1]=a[j]; j--; }
      a[j+1]=x;
    }
  };
  const partition=(lo,hi)=>{
    const p=a[lo+((hi-lo)>>1)];
    let i=lo, lt=lo, gt=hi;
    while(i<=gt){
      if(a[i]<p){ swap(i,lt); i++; lt++; }
      else if(a[i]>p){ swap(i,gt); gt--; }
      else i++;
    }
    return [lt,gt];
  };
  const qs=(lo,hi)=>{
    if(lo>=hi) return;
    if(hi-lo+1 <= TH){ insertSort(lo,hi); return; }
    const [l,r] = partition(lo,hi);
    qs(lo, l-1);
    qs(r+1, hi);
  };
  qs(0,a.length-1);
}
```

## Why This Is Asked

Tests multi-state DP design to enforce a direction-run constraint with obstacles, requiring careful state construction and both memoized and tabular implementations.

## Key Concepts

- DP with extra dimensions for last direction and run-length
- Top-down memoization and bottom-up tabulation
- Modulo arithmetic and handling blocked cells; boundary cases when L is large or grid small

## Code Example

```javascript
function countPaths(grid, L){
  const n = grid.length, m = grid[0].length, MOD = 1000000007;
  if(grid[0][0] || grid[n-1][m-1]) return 0;
  const memo = Array.from({length:n},()=>Array.from({length:m},()=>Array.from({length:2},()=>Array(L+1).fill(-1))));
  const endI=n-1, endJ=m-1;
  function dfs(i,j,dir,run){
    if(i===endI && j===endJ) return 1;
    const val = memo[i][j][dir][run];
    if(val!==-1) return val;
    let res = 0;
    // right
    if(j+1<m){
      if((dir===0 && run<L) || dir===1){
        res = (res + dfs(i, j+1, 0, dir===0 ? run+1 : 1)) % MOD;
      }
    }
    // down
    if(i+1<n){
      if((dir===1 && run<L) || dir===0){
        res = (res + dfs(i+1, j, 1, dir===1 ? run+1 : 1)) % MOD;
      }
    }
    memo[i][j][dir][run] = res;
    return res;
  }
  let ans = (dfs(0,0,0,1) + dfs(0,0,1,1)) % MOD;
  return ans;
}
```

